join public.artists a on a.name_lower = v.artist_name_lower
join public.festivals f on f.slug = v.festival_slug and f.deleted_at is null
on conflict (artist_id, festival_id, (coalesce(night, '')), (coalesce(note, ''))) do update set
  is_headliner = excluded.is_headliner;
